input.command:
docker system df -v --format json 2>/dev/null | python3 -c '
import sys,json,re
d=json.load(sys.stdin)
u={"B":1,"kB":1e3,"KB":1e3,"MB":1e6,"GB":1e9,"TB":1e12}
def b(s):
  m=re.match(r"([0-9.]+)\s*([A-Za-z]+)",s or "")
  return float(m.group(1))*u.get(m.group(2),0) if m else 0
agg={}
for r in d["BuildCache"]:
  k=(r.get("Shared"),r.get("InUse"),r.get("CacheType"))
  agg[k]=agg.get(k,0)+b(r.get("Size"))
for k,v in sorted(agg.items(), key=lambda x:-x[1]): print(k, round(v/1e9,2),"GB")
vl=[b(v.get("Size")) for v in d["Volumes"]]
print("volumes", len(vl), round(sum(vl)/1e9,1),"GB; links0:", sum(1 for v in d["Volumes"] if v.get("Links")=="0"))
'; docker system df 2>/dev/null

